// ---- Ausschlussliste hier pflegen ----
// Numerische Selling Plan IDs, die NICHT abgefragt werden sollen
const EXCLUDE_SELLING_PLAN_IDS = [
   '3156017267', // Update Payment Method
   '4016373875'  // Zahlungsmethode hinterlegen
];
// Ganze Subscription-Gruppen ausschliessen (Name muss exakt passen, case-insensitive)
const EXCLUDE_GROUP_NAMES = [
  // 'Testgruppe',
];
// ---------------------------------------

const statuses = ['ACTIVE', 'PAUSED', 'CANCELLED'];
const plans = $input.all().map(item => item.json);

const excludeIds = new Set(EXCLUDE_SELLING_PLAN_IDS.map(String));
const excludeGroups = new Set(EXCLUDE_GROUP_NAMES.map(g => g.toLowerCase()));

const result = [];
for (const plan of plans) {
  // Appstle liefert die Plan-ID als Shopify-GID zurueck (gid://shopify/SellingPlan/111111),
  // der Contract-Endpoint erwartet aber die rein numerische ID
  const numericId = String(plan.id).split('/').pop();

  if (excludeIds.has(numericId)) continue;
  if (plan.groupName && excludeGroups.has(String(plan.groupName).toLowerCase())) continue;

  for (const status of statuses) {
    result.push({
      json: {
        sellingPlanId: numericId,
        sellingPlanName: plan.frequencyName,
        groupName: plan.groupName,
        status
      }
    });
  }
}

return result;

const headers = $json.headers || {};
const totalCountHeader = headers['x-total-count'] ?? headers['X-Total-Count'] ?? '0';
const source = $('Status-Kombinationen erzeugen').item.json;

return {
  json: {
    sellingPlanId: source.sellingPlanId,
    sellingPlanName: source.sellingPlanName,
    groupName: source.groupName,
    status: source.status,
    count: parseInt(totalCountHeader, 10) || 0,
    httpStatus: $json.statusCode
  }
};

const items = $input.all();
const byPlan = {};

for (const item of items) {
  const j = item.json;
  if (!byPlan[j.sellingPlanId]) {
    byPlan[j.sellingPlanId] = {
      sellingPlanId: j.sellingPlanId,
      sellingPlanName: j.sellingPlanName,
      groupName: j.groupName,
      ACTIVE: 0,
      PAUSED: 0,
      CANCELLED: 0,
      total: 0
    };
  }
  byPlan[j.sellingPlanId][j.status] = j.count;
  byPlan[j.sellingPlanId].total += j.count;
}

return Object.values(byPlan).map(row => ({ json: row }));

